rowObjects.data:
{
  "Ventil": "{{ String(this.params.ventilName || '') }}",
  "Programm": "{{this.params.programm}}",
  "Modus": "{{this.params.modus}}",
  "System": "{{ 
    (() => {
      const stammdaten = this.params.stammdaten || [];
      const vName = String(this.params.ventilName || '').trim();
      const fVal = parseFloat(vName);

      const found = stammdaten.find(s => {
        const l = String(s.Ventil_Links || '').trim();
        const r = String(s.Ventil_Rechts || '').trim();
        return l === vName || r === vName || 
               (!isNaN(fVal) && (parseFloat(l) === fVal || parseFloat(r) === fVal));
      });
      return found ? found.System : 'Nicht gefunden';
    })() 
  }}",
  "Zeitstempel": "{{ this.params.zeitstempel || moment().format('DD.MM.YYYY HH:mm') }}",
  "Bemerkung": "{{this.params.bemerkung || ''}}",
  "Status": ""
}
